// Material 3 Expressive Showcase
// Driven by window.M3E_SPEC (autogenerated from Rust)
const SPEC = window.M3E_SPEC;

const PALETTES = SPEC.palettes;
let currentTheme = SPEC.defaultTheme || 'dark';
document.body.className = currentTheme;

function getPal() {
  return PALETTES[currentTheme];
}

// Spring physics simulation matching spring_step in src/slider.rs
function springStep(params, state, target, dt) {
  const mass = Math.max(params.mass || 1.0, 1e-4);
  const force = -params.stiffness * (state.pos - target) - params.damping * state.vel;
  const vel = state.vel + (force / mass) * dt;
  const pos = state.pos + vel * dt;
  return { pos, vel };
}

function lerpSegment(s1, s2, t) {
  return {
    sX: s1.sX + (s2.sX - s1.sX) * t,
    sY: s1.sY + (s2.sY - s1.sY) * t,
    eX: s1.eX + (s2.eX - s1.eX) * t,
    eY: s1.eY + (s2.eY - s1.eY) * t,
  };
}

function animatedIconSegments(pos, pressPos) {
  const [uId1, uId2] = SPEC.iconKeyframes.uncheckIdle;
  const [cId1, cId2] = SPEC.iconKeyframes.checkIdle;
  const [uPr1, uPr2] = SPEC.iconKeyframes.uncheckPress;
  const [cPr1, cPr2] = SPEC.iconKeyframes.checkPress;

  const id1 = lerpSegment(uId1, cId1, pos);
  const id2 = lerpSegment(uId2, cId2, pos);
  const pr1 = lerpSegment(uPr1, cPr1, pos);
  const pr2 = lerpSegment(uPr2, cPr2, pos);

  return [lerpSegment(id1, pr1, pressPos), lerpSegment(id2, pr2, pressPos)];
}

const switches = SPEC.switches.map((d) => ({
  ...d,
  displayPos: { pos: d.checked ? 1.0 : 0.0, vel: 0.0 },
  pressPos: { pos: 0.0, vel: 0.0 },
  isPressed: false,
  isHovered: false,
  canvas: null,
  ctx: null,
  statusEl: null,
}));

function initSwitches() {
  const container = document.getElementById('switches-list');
  container.innerHTML = '';
  const swm = SPEC.switchMetrics;

  switches.forEach((sw) => {
    const row = document.createElement('div');
    row.className = 'switch-row';

    const info = document.createElement('div');
    info.className = 'switch-info';

    const title = document.createElement('span');
    title.className = 'switch-title';
    title.textContent = sw.title;

    const status = document.createElement('span');
    status.className = 'switch-status';
    status.textContent = !sw.enabled ? 'Disabled' : sw.checked ? 'On' : 'Off';
    sw.statusEl = status;

    info.appendChild(title);
    info.appendChild(status);

    const canvasContainer = document.createElement('div');
    canvasContainer.className = 'switch-canvas-container' + (sw.enabled ? '' : ' disabled');

    const canvas = document.createElement('canvas');
    canvas.width = swm.trackWidth * window.devicePixelRatio;
    canvas.height = swm.trackHeight * window.devicePixelRatio;
    canvas.style.width = `${swm.trackWidth}px`;
    canvas.style.height = `${swm.trackHeight}px`;

    sw.canvas = canvas;
    sw.ctx = canvas.getContext('2d');

    if (sw.enabled) {
      canvasContainer.addEventListener('pointerdown', (e) => {
        sw.isPressed = true;
        canvasContainer.setPointerCapture(e.pointerId);
        requestFrame();
      });

      canvasContainer.addEventListener('pointerup', () => {
        if (sw.isPressed) {
          sw.checked = !sw.checked;
          sw.isPressed = false;
          status.textContent = sw.checked ? 'On' : 'Off';
          requestFrame();
        }
      });

      canvasContainer.addEventListener('pointercancel', () => {
        sw.isPressed = false;
        requestFrame();
      });

      canvasContainer.addEventListener('pointerenter', () => {
        sw.isHovered = true;
        requestFrame();
      });

      canvasContainer.addEventListener('pointerleave', () => {
        sw.isHovered = false;
        sw.isPressed = false;
        requestFrame();
      });
    }

    canvasContainer.appendChild(canvas);
    row.appendChild(info);
    row.appendChild(canvasContainer);
    container.appendChild(row);
  });
}

function renderSwitch(sw) {
  const ctx = sw.ctx;
  const dpr = window.devicePixelRatio;
  const swm = SPEC.switchMetrics;
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, swm.trackWidth, swm.trackHeight);

  const pal = getPal();
  const pos = Math.max(0, Math.min(1, sw.displayPos.pos));
  const pressPos = Math.max(0, Math.min(1, sw.pressPos.pos));

  // Thumb geometry: 28dp idle -> 34dp pressed
  // Dynamic travel matches src/components/switch.rs thumb_geometry:
  // Unchecked anchors left at 2px (expands right 28->34).
  // Checked anchors right at 52px (expands left 24->18).
  const thumbW = swm.thumbWidthIdle + (swm.thumbWidthPressed - swm.thumbWidthIdle) * pressPos;
  const travel = swm.trackWidth - 4.0 - thumbW;
  const thumbLeft = 2.0 + pos * travel;

  // Track colors matching src/switch.rs resolve_colors
  let trackColor, thumbColor, iconColor;
  if (!sw.enabled) {
    if (sw.checked) {
      trackColor = pal.onSurface;
      thumbColor = pal.surface;
      iconColor = pal.outlineVariant;
    } else {
      trackColor = pal.surfaceContainerHighest;
      thumbColor = pal.onSurface;
      iconColor = pal.surfaceContainerHighest;
    }
  } else if (sw.checked) {
    trackColor = pal.primary;
    thumbColor = pal.onPrimary;
    iconColor = pal.primary;
  } else {
    trackColor = pal.surfaceContainerHighest;
    thumbColor = pal.outline;
    iconColor = pal.surfaceContainerHighest;
  }

  // Draw track capsule
  ctx.beginPath();
  ctx.roundRect(0, 0, swm.trackWidth, swm.trackHeight, swm.trackRadius);
  ctx.fillStyle = trackColor;
  ctx.fill();

  // Draw thumb pill with subtle shadow matching GPUI .shadow_sm()
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.25)';
  ctx.shadowBlur = 3;
  ctx.shadowOffsetY = 1;
  ctx.beginPath();
  ctx.roundRect(thumbLeft, 2, thumbW, swm.thumbHeight, swm.thumbHeight / 2);
  ctx.fillStyle = thumbColor;
  ctx.fill();
  ctx.restore();

  // State layer (hover 0.08 / press 0.1)
  if (sw.enabled && (sw.isHovered || sw.isPressed)) {
    ctx.beginPath();
    ctx.roundRect(thumbLeft, 2, thumbW, swm.thumbHeight, swm.thumbHeight / 2);
    ctx.fillStyle = sw.isPressed ? 'rgba(0,0,0,0.12)' : 'rgba(0,0,0,0.06)';
    ctx.fill();
  }

  // Draw 16x16 icon strokes
  if (sw.showIcons) {
    const iconLeft = thumbLeft + (thumbW - swm.iconSize) / 2;
    const iconTop = (swm.trackHeight - swm.iconSize) / 2;
    const [seg1, seg2] = animatedIconSegments(pos, pressPos);

    ctx.strokeStyle = iconColor;
    ctx.lineWidth = swm.iconStrokeWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(iconLeft + seg1.sX, iconTop + seg1.sY);
    ctx.lineTo(iconLeft + seg1.eX, iconTop + seg1.eY);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(iconLeft + seg2.sX, iconTop + seg2.sY);
    ctx.lineTo(iconLeft + seg2.eX, iconTop + seg2.eY);
    ctx.stroke();
  }

  ctx.restore();
}

const sliders = SPEC.sliders.map((d) => ({
  ...d,
  displayPos: { pos: (d.value - d.min) / (d.max - d.min), vel: 0.0 },
  pressPos: { pos: 0.0, vel: 0.0 },
  hoverPos: { pos: 0.0, vel: 0.0 },
  isPressed: false,
  isHovered: false,
  isDragging: false,
  canvas: null,
  ctx: null,
  valueEl: null,
}));

function fractionFromValue(sl, val) {
  return Math.max(0, Math.min(1, (val - sl.min) / (sl.max - sl.min)));
}

function valueFromFraction(sl, frac) {
  let f = Math.max(0, Math.min(1, frac));
  if (sl.steps > 0) {
    const denom = sl.steps + 1;
    f = Math.round(f * denom) / denom;
  }
  return sl.min + f * (sl.max - sl.min);
}

function formatSliderValue(sl) {
  if (!sl.enabled) return 'Disabled';
  if (sl.steps > 0) return `${Math.round(sl.value)} / ${sl.max}`;
  if (sl.max === 100) return `${Math.round(sl.value)}%`;
  return `${sl.value.toFixed(2)}`;
}

function initSliders() {
  const container = document.getElementById('sliders-list');
  container.innerHTML = '';
  const slm = SPEC.sliderMetrics;

  sliders.forEach((sl) => {
    const card = document.createElement('div');
    card.className = 'card';

    const topRow = document.createElement('div');
    topRow.className = 'slider-top-row';

    const title = document.createElement('span');
    title.className = 'label-title';
    title.textContent = sl.title;

    const valueEl = document.createElement('span');
    valueEl.className = 'label-value';
    valueEl.textContent = formatSliderValue(sl);
    sl.valueEl = valueEl;

    topRow.appendChild(title);
    topRow.appendChild(valueEl);
    card.appendChild(topRow);

    const canvasContainer = document.createElement('div');
    canvasContainer.className = 'slider-canvas-container' + (sl.enabled ? '' : ' disabled');

    const canvas = document.createElement('canvas');
    sl.canvas = canvas;
    sl.ctx = canvas.getContext('2d');
    canvasContainer.appendChild(canvas);
    card.appendChild(canvasContainer);

    const TRACK_W = slm.trackWidth;
    canvas.width = TRACK_W * window.devicePixelRatio;
    canvas.height = 72 * window.devicePixelRatio;
    canvas.style.width = `${TRACK_W}px`;
    canvas.style.height = `72px`;
    sl.cssWidth = TRACK_W;

    // Pointer events for Seek & Scrub
    if (sl.enabled) {
      const updateFromPointer = (clientX) => {
        const rect = canvas.getBoundingClientRect();
        const availableW = TRACK_W - slm.cutoutTotal;
        const trackingX = clientX - rect.left - 6.0;
        const frac = Math.max(0, Math.min(1, trackingX / availableW));
        sl.value = valueFromFraction(sl, frac);
        sl.valueEl.textContent = formatSliderValue(sl);
      };

      canvasContainer.addEventListener('pointerdown', (e) => {
        sl.isPressed = true;
        sl.isDragging = true;
        canvasContainer.setPointerCapture(e.pointerId);
        updateFromPointer(e.clientX);
        requestFrame();
      });

      canvasContainer.addEventListener('pointermove', (e) => {
        if (sl.isDragging) {
          updateFromPointer(e.clientX);
          requestFrame();
        }
      });

      canvasContainer.addEventListener('pointerup', () => {
        sl.isPressed = false;
        sl.isDragging = false;
        requestFrame();
      });

      canvasContainer.addEventListener('pointercancel', () => {
        sl.isPressed = false;
        sl.isDragging = false;
        requestFrame();
      });

      canvasContainer.addEventListener('pointerenter', () => {
        sl.isHovered = true;
        requestFrame();
      });

      canvasContainer.addEventListener('pointerleave', () => {
        sl.isHovered = false;
        requestFrame();
      });
    }

    // Controls row (- / +) matching GPUI
    const controls = document.createElement('div');
    controls.className = 'slider-controls';

    const stepDownBtn = document.createElement('button');
    stepDownBtn.className = 'step-btn';
    stepDownBtn.textContent = '-';
    stepDownBtn.addEventListener('click', () => {
      if (!sl.enabled) return;
      const span = sl.max - sl.min;
      const step = sl.steps === 0 ? span / 20 : span / (sl.steps + 1);
      sl.value = valueFromFraction(sl, fractionFromValue(sl, sl.value - step));
      sl.valueEl.textContent = formatSliderValue(sl);
      requestFrame();
    });

    const stepUpBtn = document.createElement('button');
    stepUpBtn.className = 'step-btn';
    stepUpBtn.textContent = '+';
    stepUpBtn.addEventListener('click', () => {
      if (!sl.enabled) return;
      const span = sl.max - sl.min;
      const step = sl.steps === 0 ? span / 20 : span / (sl.steps + 1);
      sl.value = valueFromFraction(sl, fractionFromValue(sl, sl.value + step));
      sl.valueEl.textContent = formatSliderValue(sl);
      requestFrame();
    });

    controls.appendChild(stepDownBtn);
    controls.appendChild(stepUpBtn);
    card.appendChild(controls);

    container.appendChild(card);
  });
}

function renderSlider(sl) {
  const ctx = sl.ctx;
  if (!ctx || !sl.cssWidth) return;

  const dpr = window.devicePixelRatio;
  const slm = SPEC.sliderMetrics;
  const W = sl.cssWidth;
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, 72);

  const pal = getPal();
  const frac = Math.max(0, Math.min(1, sl.displayPos.pos));
  const press = Math.max(0, Math.min(1, sl.pressPos.pos));
  const hover = Math.max(0, Math.min(1, sl.hoverPos.pos));

  // 4px gap / 12px cutout geometry
  const availW = Math.max(W - slm.cutoutTotal, 1.0);
  const p = frac * availW;
  const thumbCx = p + 6.0;

  // Handle shrink & height expansion animation
  const thumbW = slm.thumbWidthIdle - (slm.thumbWidthIdle - slm.thumbWidthPressed) * press;
  const thumbH = slm.thumbHeightIdle + (slm.thumbHeightHover - slm.thumbHeightIdle) * hover * (1.0 - press) + (slm.thumbHeightPressed - slm.thumbHeightIdle) * press;
  const thumbTop = 36.0 - thumbH / 2.0;
  const thumbLeft = thumbCx - thumbW / 2.0;

  const activeEnd = p;
  const inactiveStart = p + 12.0;
  const showActive = activeEnd >= 8.0;
  const showInactive = W - inactiveStart >= 8.0;

  // Active track
  if (showActive) {
    ctx.beginPath();
    ctx.roundRect(0, 28, activeEnd, slm.trackHeight, [8, 2, 2, 8]);
    ctx.fillStyle = pal.primary;
    ctx.fill();
  }

  // Inactive track
  if (showInactive) {
    ctx.beginPath();
    ctx.roundRect(inactiveStart, 28, W - inactiveStart, slm.trackHeight, [2, 8, 8, 2]);
    ctx.fillStyle = pal.secondaryContainer;
    ctx.fill();
  }

  // Stop indicator dot at right cap (W - 8px)
  const stopX = W - 8.0;
  if (showInactive && Math.abs(stopX - thumbCx) >= 10.0) {
    ctx.beginPath();
    ctx.arc(stopX, 36, slm.stopDotSize / 2, 0, Math.PI * 2);
    ctx.fillStyle = pal.primary;
    ctx.fill();
  }

  // Stepped tick marks
  if (sl.steps > 0) {
    const denom = sl.steps + 1;
    const truthFrac = fractionFromValue(sl, sl.value);
    for (let i = 0; i <= denom; i++) {
      if (i === denom) continue; // Skip end coinciding with stop dot
      const t = i / denom;
      const x = t * availW + 6.0;
      if (Math.abs(x - thumbCx) < 8.0) continue;

      ctx.beginPath();
      ctx.arc(x, 36, 2, 0, Math.PI * 2);
      ctx.fillStyle = t <= truthFrac + 1e-5 ? pal.secondaryContainer : pal.primary;
      ctx.fill();
    }
  }

  // Tooltip bubble when dragging matching GPUI (56x24, rounded_full)
  if (sl.isDragging) {
    const tw = slm.tooltipWidth;
    const th = slm.tooltipHeight;
    ctx.beginPath();
    ctx.roundRect(thumbCx - tw / 2, 0, tw, th, th / 2);
    ctx.fillStyle = pal.inverseSurface;
    ctx.fill();

    ctx.font = '12px ' + getComputedStyle(document.body).fontFamily;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = pal.inverseOnSurface;
    ctx.fillText(sl.value.toFixed(1), thumbCx, th / 2);
  }

  // Thumb "|" handle
  ctx.save();
  if (press > 0.01) {
    ctx.shadowColor = 'rgba(0,0,0,0.3)';
    ctx.shadowBlur = 8 * press;
    ctx.shadowOffsetY = 2 * press;
  } else if (hover > 0.01) {
    ctx.shadowColor = 'rgba(0,0,0,0.2)';
    ctx.shadowBlur = 4 * hover;
    ctx.shadowOffsetY = 1 * hover;
  }
  ctx.beginPath();
  ctx.roundRect(thumbLeft, thumbTop, thumbW, thumbH, thumbW / 2);
  ctx.fillStyle = sl.enabled
    ? pal.primary
    : (currentTheme === 'dark' ? 'rgba(230, 225, 229, 0.38)' : 'rgba(29, 27, 32, 0.38)');
  ctx.fill();
  ctx.restore();

  ctx.restore();
}

const SPRINGS = SPEC.springs;
const DT = SPRINGS.dt;
const SLIDER_SPRING = SPRINGS.sliderExpressive;
const STANDARD_SPRING = SPRINGS.sliderStandard;
const SWITCH_SPRING = SPRINGS.switch;
const PRESS_SPRING = SPRINGS.press;
const HOVER_SPRING = SPRINGS.hover;

let isAnimating = false;

function requestFrame() {
  if (!isAnimating) {
    isAnimating = true;
    requestAnimationFrame(animate);
  }
}

function renderAll() {
  switches.forEach(renderSwitch);
  sliders.forEach(renderSlider);
}

function animate() {
  let needsRepaint = false;

  // Advance switches
  switches.forEach((sw) => {
    const targetPos = sw.checked ? 1.0 : 0.0;
    const targetPress = sw.isPressed ? 1.0 : 0.0;

    const nextPos = springStep(SWITCH_SPRING, sw.displayPos, targetPos, DT);
    const posSettled = Math.abs(nextPos.pos - targetPos) < 0.0005 && Math.abs(nextPos.vel) < 0.0005;
    sw.displayPos = posSettled ? { pos: targetPos, vel: 0.0 } : nextPos;

    const nextPress = springStep(PRESS_SPRING, sw.pressPos, targetPress, DT);
    const pressSettled = Math.abs(nextPress.pos - targetPress) < 0.0005 && Math.abs(nextPress.vel) < 0.0005;
    sw.pressPos = pressSettled ? { pos: targetPress, vel: 0.0 } : nextPress;

    if (!posSettled || !pressSettled) {
      needsRepaint = true;
    }
    renderSwitch(sw);
  });

  // Advance sliders
  sliders.forEach((sl) => {
    const targetFrac = fractionFromValue(sl, sl.value);
    const targetPress = sl.isPressed || sl.isDragging ? 1.0 : 0.0;
    const targetHover = sl.isHovered ? 1.0 : 0.0;

    const springParams = sl.expressive ? SLIDER_SPRING : STANDARD_SPRING;
    const nextFrac = springStep(springParams, sl.displayPos, targetFrac, DT);
    const fracSettled = Math.abs(nextFrac.pos - targetFrac) < 0.0005 && Math.abs(nextFrac.vel) < 0.0005;
    sl.displayPos = fracSettled ? { pos: targetFrac, vel: 0.0 } : nextFrac;

    const nextPress = springStep(PRESS_SPRING, sl.pressPos, targetPress, DT);
    const pressSettled = Math.abs(nextPress.pos - targetPress) < 0.0005 && Math.abs(nextPress.vel) < 0.0005;
    sl.pressPos = pressSettled ? { pos: targetPress, vel: 0.0 } : nextPress;

    const nextHover = springStep(HOVER_SPRING, sl.hoverPos, targetHover, DT);
    const hoverSettled = Math.abs(nextHover.pos - targetHover) < 0.0005 && Math.abs(nextHover.vel) < 0.0005;
    sl.hoverPos = hoverSettled ? { pos: targetHover, vel: 0.0 } : nextHover;

    if (!fracSettled || !pressSettled || !hoverSettled) {
      needsRepaint = true;
    }
    renderSlider(sl);
  });

  if (needsRepaint) {
    requestAnimationFrame(animate);
  } else {
    isAnimating = false;
  }
}

// Theme switch handler
document.getElementById('theme-toggle').addEventListener('click', () => {
  currentTheme = currentTheme === 'dark' ? 'light' : 'dark';
  document.body.className = currentTheme;
  document.getElementById('theme-toggle').textContent =
    currentTheme === 'dark' ? 'Light Theme' : 'Dark Theme';
  renderAll();
  requestFrame();
});

// Initialize on DOM load
initSliders();
initSwitches();
renderAll();
requestFrame();
